import { Order } from './types';

export interface PageQuery {
  tenant: string;
  limit: number;
  after?: { createdAt: string; id: string };
}

function compareOrders(a: Order, b: Order): number {
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  if (a.id !== b.id) return a.id < b.id ? -1 : 1;
  return 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  list(tenant: string): Order[] {
    return this.rows.filter(row => row.tenant === tenant).sort(compareOrders);
  }

  // Returns up to `limit` orders for the tenant, sorted by (createdAt, id),
  // strictly after `after` when given, plus whether more matching orders exist.
  // Filtering by tenant happens before the cursor comparison, and the cursor is
  // compared by value, so it works even if its row no longer exists.
  listPage(query: PageQuery): { items: Order[]; hasMore: boolean } {
    const after = query.after;
    const matching = this.rows
      .filter(row => row.tenant === query.tenant)
      .filter(row => after === undefined ||
        compareOrders(row, { tenant: row.tenant, createdAt: after.createdAt, id: after.id, total: 0 }) > 0)
      .sort(compareOrders);
    return {
      items: matching.slice(0, query.limit),
      hasMore: matching.length > query.limit,
    };
  }
}
