const assert = require('node:assert/strict');

        const { OrderHandler } = require('../.build/handler');
        const { OrderRepository } = require('../.build/repository');
        const handler = new OrderHandler(new OrderRepository([
          { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
          { id: 'x', tenant: 'b', createdAt: '2026-01-01', total: 3 },
          { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 }
        ]));
        assert.deepEqual(handler.list({ tenant: 'a', limit: 1 }).items.map(x => x.id), ['a']);
        assert.throws(() => handler.list({ tenant: 'a', limit: 0 }), /invalid request/);

        // Cursor pagination over equal dates, across a tenant boundary, with a deleted cursor row.
        const rows = [
          { id: 'c', tenant: 'a', createdAt: '2026-01-01', total: 1 },
          { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
          { id: 'b', tenant: 'a', createdAt: '2026-01-01', total: 1 },
          { id: 'z', tenant: 'o', createdAt: '2026-01-01', total: 1 },
          { id: 'd', tenant: 'a', createdAt: '2026-01-03', total: 1 },
        ];
        const snapshot = JSON.stringify(rows);
        const h2 = new OrderHandler(new OrderRepository(rows));
        const p1 = h2.list({ tenant: 'a', limit: 2 });
        assert.deepEqual(p1.items.map(x => x.id), ['a', 'b']);
        assert.equal(p1.nextCursor, '2026-01-01|b');
        const p2 = h2.list({ tenant: 'a', limit: 2, cursor: p1.nextCursor });
        assert.deepEqual(p2.items.map(x => x.id), ['c', 'd']);
        assert.equal(p2.nextCursor, null);
        // Cursor pair of another tenant's row still filters correctly.
        assert.deepEqual(h2.list({ tenant: 'a', limit: 10, cursor: '2026-01-01|z' }).items.map(x => x.id), ['d']);
        // Cursor whose row was deleted (not in input) resumes strictly after the pair.
        const h3 = new OrderHandler(new OrderRepository([rows[0], rows[4]]));
        assert.deepEqual(h3.list({ tenant: 'a', limit: 10, cursor: '2026-01-01|b' }).items.map(x => x.id), ['c', 'd']);
        assert.equal(JSON.stringify(rows), snapshot);
        for (const bad of [
          { tenant: '', limit: 1 }, { tenant: 'a', limit: 101 }, { tenant: 'a', limit: 1.5 },
          { tenant: 'a', limit: 1, cursor: '' }, { tenant: 'a', limit: 1, cursor: 'x' },
          { tenant: 'a', limit: 1, cursor: 'a|b|c' }, { tenant: 'a', limit: 1, cursor: '|b' },
        ]) assert.throws(() => h2.list(bad), /invalid request/);
EOF
